/** Rend une icône ; `$classe` reçoit les utilitaires Tailwind de taille. */
function icone(string $nom, string $classe = 'size-5'): string
{
    $trace = TRACES_ICONES[$nom] ?? TRACES_ICONES['jauge'];
    return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" '
        . 'stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" '
        . 'class="' . e($classe) . '" aria-hidden="true">' . $trace . '</svg>';
}
